"""NLI-style entailment check against retrieved sources (cross-encoder)."""

from __future__ import annotations

from typing import Any

from sentence_transformers import CrossEncoder

# Generated by GitHub Copilot - Nov-01-2026
from app.guardrails.models import GuardrailResult


class HallucinationCheckerGuardrail:
    name = "hallucination_checker"

    def __init__(self) -> None:
        self._model: CrossEncoder | None = None

    def _ensure(self) -> CrossEncoder:
        if self._model is None:
            self._model = CrossEncoder("cross-encoder/nli-deberta-v3-small")
        return self._model

    async def run(self, text: str, context: dict[str, Any] | None, **params: Any) -> GuardrailResult:
        entailment_threshold = float(params.get("entailment_threshold", 0.35))
        action = str(params.get("_action", params.get("action", "warn")))
        sources = (context or {}).get("retrieval_chunks") or []
        if not sources or not text.strip():
            return GuardrailResult(text=text, blocked=False)

        model = self._ensure()
        premises = [s.get("text", "")[:512] for s in sources[:6] if s.get("text")]
        if not premises:
            return GuardrailResult(text=text, blocked=False)

        pairs = [[p, text[:512]] for p in premises]
        # Generated by GitHub Copilot - Nov-01-2026
        # This NLI model returns contradiction, entailment and neutral logits.
        scores = model.predict(pairs, show_progress_bar=False, apply_softmax=True)
        max_entail = float(scores[:, 1].max()) if len(scores) else 0.0

        if max_entail < entailment_threshold:
            msg = f"Low entailment vs sources ({max_entail:.2f} < {entailment_threshold})"
            if action == "block":
                return GuardrailResult(text="", blocked=True, warnings=[msg])
            return GuardrailResult(text=text, blocked=False, warnings=[msg])
        return GuardrailResult(text=text, blocked=False)
